// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzTimestamp, uint256 fuzzBlockNumber) public {
        vm.assume(fuzzTimestamp > 0);
        vm.warp(fuzzTimestamp);
        vm.roll(fuzzBlockNumber);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "first call failed");

        assertEq(c.pastBlockTime(), fuzzTimestamp);
    }
}
